决策顺序是：先确认课程供给与自带许可，再查部件完整和机械固定，之后分别看镜片状态与光源安全。发现固定霉斑、明显雾化或划痕，载物台和准焦无法稳定工作，或供电存在破损焦痕时，不按普通可用设备接手。', _utf8mb4'["显微镜","物镜","载物台","光源","霉斑"]', 0, 0, @seed_author_id, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 207 DAY), DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 207 DAY), 0
