适合发布或接手的状态，通常是铅笔轻划、页边少量可辨认的短注、没有粘死页面的便签。荧光笔大面积覆盖文字、整段涂改、胶带残留、夹页受潮变形，则应按阅读干扰和后续引用风险重新估价，严重时直接放弃。

## 先要求四类照片

卖家应拍目录页、任意三处正文页、注释页和空白页。三处正文不要只挑最干净的页面，最好分别来自开头、中段和后半本。买家由此判断批注是集中在少数篇目，还是贯穿全书；只展示一处样页，不能代表整本状态。

目录页用于确认哪些文章可能被重点标记，正文页用于观察字迹、划线和遮挡程度，注释页用于查看页码、脚注或译注是否被写满，空白页则能反映纸张泛黄、受潮、印章和残胶情况。可以直接询问：“请再拍后半本一页未挑选的正文，以及所有有胶带或便签的位置。”

## 把痕迹分成四档

铅笔轻划一般对识读影响较小，但不要默认可以无损擦除；纸张可能留下压痕，擦拭也可能伤害印刷。页边的短笔记若字迹清楚，能够提示人物关系、意象或译注位置，可能对写报告有帮助，但它仍只是辅助索引。

荧光笔遮住字词、黑笔覆盖句子、整段涂改，都会增加回看原文的困难。胶带粘住页面会使纸张无法平整翻动，便签残胶可能撕裂纸面；夹页若受潮或长期挤压，也可能造成折痕和装订处松动。后几类不只是外观问题，还会影响阅读连续性和引文确认。

## 按使用目的比较

若主要用于论文或读书报告，逐一检查可能引用的关键段落：文字是否完整，页码是否可见，脚注、译者说明和版本信息是否被划线或涂写遮住。批注不能替代自己回到原文核对上下文，也不能证明某句话就是作者或老师的重点。若关键引文页无法清楚阅读，干净本即使笔记少，也更适合作为工作底本。

若只是日常阅读，可以接受少量篇章索引和译注提示。前提是正文仍能连续读完，页面可以自然摊开，便签能取下或至少不妨碍翻页。比较两本书时，可将“可利用的笔记”与“必须避开的遮挡”分开记录，不要用批注数量直接判断价值。

## 面交复核与退出

面交时从卖家没有展示的后半本开始翻查，再抽查目录标出的重点篇目、注释页和空白页。若实际批注密度明显高于样张，或出现未说明的涂改、残胶、缺页、松动装订，就按实际状态重新判断；无法接受时不接手。最终顺序是：先确认正文完整可读，再确认批注是否能提供索引，最后才考虑它是否比干净本更方便。', _utf8mb4'["文学选本","批注","划线","读书报告","便签","论文"]', 0, 0, @seed_author_id, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 277 DAY), DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 277 DAY), 0
