检查顺序是：型号与编号、外观和接口、开关机、对焦与快门、拍摄写卡、回放或导出，最后核对配件并付款。任何一项基本功能无法测试，或卖家以赶时间为由阻止写卡和回放，均应离场。', _utf8mb4'["相机","面交","验货","存储卡"]', 0, 0, @seed_author_id, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 303 DAY), DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 303 DAY), 0
