发生争议时按时间线提交原发布照片、原始聊天、付款记录、交付记录和双方确认内容：先证明当时展示了什么，再证明成交约定是什么，最后证明交付了什么。不要事后编辑帖子掩盖划线、缺页或访问码状态。判断顺序是先完整记录商品，再确认范围和价格，最后用交付证据闭合链条；关键状态无法证明时，应在成交前明确披露或停止交易。', _utf8mb4'["教材","缺页","聊天记录","证据"]', 0, 0, @seed_author_id, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 318 DAY), DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 318 DAY), 0
