决策顺序是：先固定发布内容，再逐项记录变更，随后对应付款与交付，争议时用时间线指向原始材料；关键节点缺失且无法补充确认时，只能按现有条件重新协商。', _utf8mb4'["纠纷","聊天记录","付款","证据"]', 0, 0, @seed_author_id, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 321 DAY), DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 321 DAY), 0
