SELECT @seed_post_id_base + 194 * @seed_snowflake_step, _utf8mb4'课程资料放二手移动硬盘：它只能做副本，不能做唯一仓库', _utf8mb4'我考虑移动硬盘时，最重要的原则不是容量够不够，而是任何一块二手存储介质都不应该保存唯一一份课程资料。硬盘可以帮助我建立第二副本，但不能因为买了它，就把电脑和云端文件全部清掉。

## 先画出资料的两份位置

我会按课程项目、照片视频、软件环境和可重新下载文件分类。不可替代的报告、代码和原始素材至少保留在两个独立位置；安装包和缓存可以不占备份额度。这样算出的容量比把电脑整个目录复制一遍更接近真实需求。

备份频率也要写清。代码每天变化，可以同时使用版本管理；大型视频素材每次活动后同步；普通课程讲义每周整理一次。没有固定节奏，容量再大也只是一个偶尔想起才连接的盒子。

## 健康信息和连续读写一起看

我会查看硬盘型号、通电时间和可读取的健康信息，再进行较长时间的文件写入与回读。一次测速很快不能说明稳定性，连续复制时是否掉盘、速度是否反复归零、系统是否出现输入输出错误更关键。机械硬盘还要留意异常敲击和震动，固态盘则不能只看标称速度。

接口、硬盘盒和线材是一条完整链路。我会用自己的常用设备连接，轻微移动线头，观察是否断开；再换一根可靠线排除线材影响。接口外形相同不代表协议速度相同，也不代表手机、平板或路由器都能供电识别。

## 容量选择要给版本和临时文件留余地

备份不是只保留最新文件。毕业设计可能需要回到上周版本，视频项目也会产生代理文件和导出成品。我会按照现有资料量，估算一个学期增长，再为阶段版本留空间。容量刚好等于当前文件总量，很快就会因为整理困难而放弃同步。

硬盘带出宿舍时还要考虑抗震和收纳。机械盘运行中不移动，使用后安全弹出；重要展示不要只带一块盘去现场，关键文件另存一个小副本。移动硬盘提供便利，但不应成为新的单点风险。

## 用恢复演练检查备份是否真的有效

每月我会随机选择一个课程文件夹，复制到另一位置并打开其中的文档、图片和项目文件。只有能够恢复的副本才叫备份。同步软件显示完成，不等于每个文件都可读；发现错误后也要回查另一份来源。

适合我的二手移动硬盘，需要健康状态没有明显警告，连续读写稳定，接口匹配现有设备，容量覆盖阶段版本。更重要的是，它进入固定的双副本流程，而不是把所有资料从一个地方搬到另一个地方。', _utf8mb4'["移动硬盘","资料备份","项目文件","购买经验"]', 0, 0, @seed_author_id, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 345 DAY), DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 345 DAY), 0
