SELECT @seed_post_id_base + 198 * @seed_snowflake_step, _utf8mb4'二手台灯放进宿舍前：我先用课本检查照明范围和反光', _utf8mb4'我不会把“护眼”两个字直接当作效果保证。宿舍台灯真正要解决的是书本和草稿纸能否被均匀照亮，同时不直射眼睛、不在平板上形成亮斑，也不把光投到已经休息的室友床位。

## 用完整桌面测试，不只照一张白纸

我会按平时布局放好教材、笔记本、键盘和平板，再把台灯移到计划位置。打开一本较大的书，观察书脊两侧、草稿纸边缘和手写区域是否存在明显明暗差。灯面很亮但只能照到桌面中心，写到右侧仍要挪灯，并不方便。

惯用手会影响摆放。右手写字通常把灯放左侧更少遮挡，但还要考虑电脑屏幕和固定书架。夹式台灯节省底座位置，却要求桌板厚度、夹口深度和夹持处结实；底座款稳定，但可能占掉水杯或鼠标区域。

## 亮度档位要看常用的两档

我会在白天补光和夜间主照明两种状态下调整亮度，检查最低档是否仍太刺眼、中档是否足够阅读。色温变化很多不一定有用，我更关心切换后亮度是否突然跳变、触控按键是否灵敏，以及断电重开是否记住常用设置。

所谓频闪不能只靠手机画面简单下结论，但手机慢动作出现明显滚动条、眼睛很快疲劳或亮度持续抖动，都值得谨慎。电源适配器和线材要规格匹配，接口接触稍动就灭灯，会在长时间写作业时反复打断。

## 平板反光和室友感受单独检查

我会把平板调到常用角度，显示深色和浅色页面，移动灯头查看是否出现大面积反射。能调整灯臂并不代表每个角度都稳定，悬停后缓慢下坠会让光线不断变化。

夜间还要站到室友床位方向看一次，确认光源本身没有直接进入视线。增加遮光、降低灯头或改变方向，往往比单纯调暗更有效。台灯改善个人阅读，不应把光污染转移给别人。

## 一周后看是否还频繁挪灯

合适的台灯应该在固定位置覆盖大部分任务。我会记录一周里因光线不够、反光或占地挪动了几次。频繁调整说明灯臂范围或桌面布局不匹配；只在画大图时需要移动，则可以接受。

最终我更看重照明范围、常用亮度、灯臂稳定、适配器状态和室友影响。复杂模式可以少，基础光线必须在真正的宿舍桌面上舒服而稳定。', _utf8mb4'["台灯","宿舍照明","阅读","购买经验"]', 0, 0, @seed_author_id, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 349 DAY), DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 349 DAY), 0
