SELECT @seed_post_id_base + 212 * @seed_snowflake_step, _utf8mb4'体测训练买二手跑步鞋：鞋底看着新，中底也可能已经累了', _utf8mb4'我挑跑步鞋时不会先看鞋面有多新。鞋子可能很少沾灰，却已经长期受压；也可能外观有正常折痕，中底仍然均匀。对体测训练来说，尺码、鞋楦和左右脚受力是否适合，比颜色和原价更重要。

## 先按跑步状态测脚

我会在下午或运动后测量双脚长度和最宽处，因为脚在活动后会略微膨胀。再穿上训练时常用的袜子，给脚趾留合理活动空间。只报平时休闲鞋尺码不够，同一尺码在不同鞋楦上可能顶脚或过宽。

试穿后快走、慢跑和急停，观察后跟是否滑动、前掌是否挤压、足弓位置是否顶得不自然。站着觉得柔软，并不代表跑几圈不会磨脚。我会以更大的那只脚为准，不指望通过“穿开”解决明显不合。

## 磨损位置要左右对照

把两只鞋并排放在平面上，看后跟是否向一侧倾斜，中底有没有明显塌陷、褶皱不对称或局部变硬。再看大底常接触地面的区域，左右磨损差异很大，可能意味着鞋已经形成原使用者的受力习惯。

弯折位置应主要在前掌，鞋身被轻扭就过度变形、后跟支撑片松软，都会改变稳定。鞋底纹路仍在不代表中底回弹完整，因此我不会用剩余纹路单独估计跑量。

## 卫生处理有明确边界

鞋垫、内衬和鞋口直接接触汗液。我会检查是否能拆洗、是否有霉点、破损和无法去除的气味。鞋垫可以更换，但内衬大面积污染或后跟磨破会持续摩擦。对个人无法接受的贴身卫生状态，不因为外观好看降低标准。

清洁后还要彻底晾干，不能用高温强行烘烤改变材料。鞋面轻微污渍通常只是成色，胶层开裂、鞋底脱离和中底粉化则属于结构问题。

## 用三次短跑再增加距离

我不会第一次穿就完成长距离训练，而是先走路，再进行几次短跑，记录脚趾、足弓、膝部和磨脚位置。任何持续疼痛都应停止使用并重新判断，不靠忍耐适应。

适合体测训练的二手跑步鞋，应当尺码与鞋楦匹配，左右结构没有明显失衡，贴身部分可接受且清理完整。它不需要像新鞋一样洁白，但必须让我连续训练时不被鞋本身打断。', _utf8mb4'["跑步鞋","体测","中底","购买经验"]', 0, 0, @seed_author_id, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 363 DAY), DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 363 DAY), 0
