## 随机试读比从序言开始有效

我会从前、中、后各选一篇，记录单篇需要多久、是否必须了解上下文、读完有没有想回看。睡前只有十几分钟时，篇幅过长可能总在中间停下；过于碎片化又可能没有完整阅读感。

主题也要看目录。旅行、成长、自然或评论类散文带来的节奏不同，合集若只是把多个时期文章堆在一起，未必每部分都符合当前兴趣。

## 纸张和排版影响睡前体验

我会在夜间常用灯光下读几页，查看字号、行距、纸张反光和书能否自然摊开。小开本便于拿在床边，字体过小则会增加疲劳。精装很漂亮但单手持握重，也可能更适合书桌而非睡前。

二手批注要看位置。页边少量感想可以提供另一种阅读视角，整段荧光覆盖和密集改写会抢走自己的节奏。霉味、水渍和纸张粘连则优先于内容喜好排除。

## 摘抄不是必须完成的作业

我会先纯阅读一周，只在真正想保留时标记页码。为了让买书显得有价值而强迫每篇摘抄，会把放松变成任务。写作积累也应围绕自己的表达需要，不是收集越多句子越好。

如果电子版更方便搜索，我会把纸质书留给长时间阅读，把少量笔记转入自己的系统。工具分工清楚，避免同一内容在书页、手机和本子里重复维护。

## 两周后的主动翻阅次数

我会把散文集放在床边或书桌固定位置，统计两周里主动拿起几次。只有因为“已经买了”才提醒自己读，说明选题或语言并不适合当前阶段。

适合我的二手散文集，应有可在零碎时间完成的篇幅，主题和语言愿意继续读，排版支持夜间阅读，书页状态干净可靠。作者热度能让我认识一本书，不能替我完成长期相处。

如果图书馆有同版本，我会先借两周并记录主动翻阅次数。借阅期内已经多次续读，购买纸质本才是延长既有习惯；借来始终没打开，则说明当前兴趣尚不足以支持收藏。', _utf8mb4'["散文集","短时阅读","阅读节奏","购买经验"]', 0, 0, @seed_author_id, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 386 DAY), DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 386 DAY), 0
