## 用随机三页测查词密度

我会避开开头导读，从前中后各选一页，正常阅读并只标记影响理解的词。每页若需要频繁停下，阅读会变成逐句翻译；少量生词不妨碍情节，才更接近泛读。目标若是精读，难度可以提高，但要接受进度更慢。

对话多、叙述直接的小说通常更容易进入，年代较久或文化背景复杂的作品可能需要注释。分级读物、双语辅助和电子词典版都可作为过渡，不用把直接读最难原版当成唯一进步路径。

## 字号与行距影响长时间阅读

廉价小开本可能压缩字号和页边距，携带轻却读得累。我会连续读二十分钟，观察纸张透字、行距、装订能否摊开，以及单手拿书的重量。脚注过小或跨页频繁，也会增加中断。

二手书中的中文释义和生词标记未必适合我。少量铅笔记录可以参考，整页翻译会让我提前依赖答案。还要检查缺页、霉斑和书脊，原版身份不能提高对卫生与完整性的容忍。

## 故事兴趣与语言目标分开记录

我会读完前三章后分别打分：故事是否想继续，语言是否在可承受范围。故事喜欢但语言太难，可以换简写或中文版先了解；语言合适但内容没兴趣，也不必为了学习意义硬读。

查词工具只记录反复出现、真正影响理解的词，不把每个陌生形容词都加入清单。泛读需要保持向前推进，词汇积累是阅读结果，不应吞掉全部时间。

## 两周后看能否形成固定页数

我会设置每天十到二十页的轻量目标，观察两周是否自然完成。总在同一章重启，说明难度或兴趣不匹配，应换书而不是继续增加原版库存。

开始长期阅读前，我会检查目录与正文是否缺页，并测试连续读十页后的查词次数。适合我的二手英文小说，应有可控查词密度、舒服排版、完整书页和真正感兴趣的故事。读完一本略低于极限的书，比收藏几本一直停在第一页的名著更有训练价值。', _utf8mb4'["英文原版","泛读","词汇难度","购买经验"]', 0, 0, @seed_author_id, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 387 DAY), DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 387 DAY), 0
