## 选本范围决定内容密度

单一作者诗集、年代选本和主题合集的结构不同。我会查看编选说明、收录年代、是否有重复版本，以及自己喜欢的篇目占多少。只为一首作品购买厚合集，图书馆借阅或单篇合法阅读可能更合适。

译诗还要比较译者。节奏、意象和断行会因版本变化，我会选同一首并排朗读，判断哪种语言更自然。不能只凭封面上“经典译本”替代自己的声音体验。

## 朗读与默读对排版要求不同

社团朗读时，我更关注字号、换页位置和书能否单手稳定拿住；个人摘抄则看页边留白、目录索引和纸张是否适合标记。精装硬壳便于保存，却可能在朗读时较重。

二手批注如果只是页码和少量感想，不一定干扰；整首被不同颜色覆盖，会影响自己理解停顿。纸张霉斑、粘连和装订松散仍是优先检查项，不因诗集年代久就视为自然收藏痕迹。

## 摘抄只保留真正回看的部分

我会在阅读时先贴页码标记，一周后仍想保留的内容才摘进本子。这样能区分当下觉得优美与长期对自己有意义，不让摘抄变成抄写任务。

参加朗读活动时，还会查看作品使用和引用要求，准确记录作者、译者与版本信息。喜欢一首诗不等于可以忽略署名和文本差异。

## 一个学期后的书架位置

我会观察一个学期内主动翻阅次数，以及是否只在社团活动前拿出。高频重读值得长期保存，阶段性活动用书可以依赖借阅。

用于公开朗读时，我还会核对版权页、作者与译者信息，把节目单上的署名写准确。若选本对原作出处标注含糊，它不适合作为正式引用依据，可以只用于个人阅读。一本诗集能否支持查找原始信息，也是我决定长期保留的重要原因。

适合我的二手诗集，应有足够多真正喜欢的篇目，版本语言适合朗读或默读，排版与装订可靠。收藏价值来自多次回到文本，不只来自封面与一句名句。', _utf8mb4'["诗集","朗读","篇目","购买经验"]', 0, 0, @seed_author_id, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 388 DAY), DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 388 DAY), 0
