## 先确认课程使用哪一版文本

我会查看课程是否指定译者、选段或页码。不同译本可能调整人物译名和台词，社团成员混用版本会增加对词困难。个人延伸阅读可以选喜欢的译本，集体任务优先统一文本。

作品集还要看是否收录完整剧本、删节版还是节选。目录写有作品名，不代表附录与幕次完整。课程要分析结构时，删节会直接影响使用。

## 用一场对白测试排版

我会选角色较多的一场，连续朗读几页，观察角色名是否突出、换行是否清楚、舞台说明会不会与台词混淆。字号、页边和书能否摊平也很重要，排练中没人能一直按住书脊。

角色表、译者说明、时代背景与注释的价值不同。第一次阅读需要人物关系，论文准备可能需要版本与注释；排演则更需要快速查场次。我会按主要任务选择，不追求附录越厚越好。

## 批注可能帮助排演，也可能限制理解

二手戏剧书常有角色分配、停顿和走位标记。若恰好用于观察排演思路，少量笔记有参考价值；若课程要求独立分析，密集解释会抢先给出结论。用铅笔且不遮正文的标记更容易处理。

还要逐页查看是否有裁页、脱页和水渍，尤其是常排演场次可能翻动最多。缺一页对白会让整场无法使用，不能用其他章节完整来平均。

## 集体使用前统一页码

我会在读书会或排练开始前确认所有人版本，必要时制作“场次—页码”对照，而不是活动中临时寻找。个人书上只记录自己的角色与问题，不把公共文本改成别人难读的工作本。

如果一本书由多人轮流使用，我会另备可移除的角色标签，不直接用粗笔覆盖角色名。排练结束后清点页签、恢复原页，下一位成员仍能按自己的角色阅读。把个人工作痕迹与正文分开，能延长戏剧文本的共同使用寿命。

适合我的二手戏剧作品集，应与课程或社团版本对应，剧本完整，角色与舞台说明排版清楚，书能自然摊开，批注不会遮挡对白。戏剧书服务共同阅读，定位效率与文本本身同样重要。', _utf8mb4'["戏剧集","角色表","舞台说明","购买经验"]', 0, 0, @seed_author_id, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 390 DAY), DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 390 DAY), 0
