## 先建立七天使用位置

我会先用自己已有的小规格产品，分别放在书包和宿舍，记录七天使用次数。总忘记使用，说明需要调整位置和习惯，不是增加库存；每天多次使用，才适合考虑更大容量。

随身款要放进笔袋或侧袋，盖子不能容易松开。宿舍款可以大些，但泵头和瓶口仍需保持清洁。容量选择服务位置，不必一支承担所有场景。

## 只考虑原包装未开封

护肤品属于直接接触皮肤的产品，我只考虑外盒与容器原封、批次和日期清楚、储存情况合理的商品。已经开封、试用过或封口状态说不清，不因为剩余量多继续考虑。

包装受热变形、内容物渗漏或气味异常，也不能只看日期判断。临近使用期限时，按自己七天记录估算能否正常用完，不为了避免浪费强迫增加涂抹。

## 香味和肤感需要来自熟悉产品

未开封意味着无法先试当前这一支，因此更适合选择自己用过的同款。没有使用经验时，我会从正规渠道的小规格新品了解肤感，而不是一次接手大容量。香味在公共教室可能比在商场试闻更明显。

配料与个人皮肤状况需要自行判断。出现持续刺激、红痒等不适应停止使用，必要时寻求专业建议；低价和库存都不应成为继续使用的理由。

## 一个月后看是否自然用完

我会记录书包款与宿舍款谁使用更多，避免下一次重复购买相同位置。若一支总被遗忘，就把它移到洗手后的固定路径，而不是再买新香味增加兴趣。

对我来说，书包款重点是旋盖牢固和少量取用，宿舍款重点是洗手后伸手可得。两支同时存在也必须有明确位置分工；如果只是因为礼盒里有多支而分散摆放，往往每支都开了却没有一支按期用完。

适合我的未开封护手霜，应是熟悉配方和香味，包装日期可靠，容量匹配真实次数，并能放在容易使用的位置。每天记得涂，比一次买得多更接近需求。', _utf8mb4'["护手霜","未开封","随身护理","购买经验"]', 0, 0, @seed_author_id, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 391 DAY), DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 391 DAY), 0
