SELECT @seed_post_id_base + 252 * @seed_snowflake_step, _utf8mb4'考研数学辅导书别照搬整套书单：先判断自己在基础轮还是强化轮', _utf8mb4'学长完整书单很容易让人觉得照着买就不会漏，但基础轮、强化轮和冲刺轮需要的资料不同。我会先用一套诊断题判断自己卡在概念、计算还是综合应用，再选一本能解决当前问题的书，而不是一次接下所有阶段。

## 用一章试出解析风格

我会挑自己薄弱又学过的章节，先独立做三到五题，再阅读解析。好的解析应说明从已知条件到方法选择的过程，不只是把公式排列得很完整。看懂答案后合上书，能否重新写出关键步骤，才能判断这本书是否适合。

基础轮更需要定义、典型例题与计算规范，强化轮才逐渐增加综合性。当前连基本公式使用都不稳定，直接购买难题集可能只会增加挫败和抄答案次数。

## 二手填写状态决定用途

我会翻看每章例题、练习区和空白页。答案只写在独立解析册，主书保持空白，适合第一次练习；题旁已经写满过程，更适合作为查阅材料。铅笔痕能否擦净也要实际检查，反复擦除可能损伤纸张。

错题标记本身不等于高价值，别人的薄弱点与我不同，错误批注还需要重新验证。缺页、裁页和解析册不全会破坏题目链路，不能用总页数很多抵消。

## 系列书不必同一时间补齐

我会为当前阶段只保留一本主线资料，配合真题和自己的错题本。两个讲解体系同时推进，容易在相似章节重复做题，却没有完成复盘。完成七成以上并明确下一阶段缺口，再决定是否补同系列。

宿舍书桌与每日携带也要考虑。厚重大部头适合固定放宿舍，日常自习只带当前章节或薄册；为了“全”每天背一整套，会降低使用意愿。

## 四周后检查进度与回做

我会记录四周完成页数、独立正确率和错题回做情况。只不断翻新章节、旧错题仍不会，说明问题在学习循环，不是资料数量不足。

适合我的二手考研数学辅导书，应匹配当前阶段，解析能帮助独立重做，主练习区保留足够空白，卷册完整。书单提供方向，诊断与执行才决定哪一本现在有用。

每完成一章，我会在目录旁只写完成日期和回做日期，不写“已掌握”这种模糊结论。第二次仍出错的章节继续留在当前阶段，避免被进度页数制造的完成感带走。', _utf8mb4'["考研数学","复习阶段","辅导书","购买经验"]', 0, 0, @seed_author_id, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 403 DAY), DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 403 DAY), 0
