## 从可验证的课程信息开始

我会查看题册标注的学院、课程代码、年份与考试性质，是期中、期末还是补考。再把题目章节与当前课程目录对应。无法说明来源的整理题可以当普通练习，不能用来推断本班必考重点。

教师可能调整题型与覆盖范围，较早年份适合观察核心概念，不能简单按出现次数预测今年题目。我会把历年题当作结构样本，而不是押题清单。

## 先做一套，不先看答案频率

我会在学完主要章节后计时完成一套，记录题型、分值、耗时和知识点。没有完成课程基础就直接刷题，容易把暂时不会误判成考试超纲。

答案质量也需要核对。只有最终结果的计算题无法支持纠错，整理者给出的主观题答案可能只是个人版本。我会回到教材、课堂笔记和教师明确材料验证，不把打印得整齐等同权威。

## 二手题册的书写痕迹要区分

题目页若已圈出正确选项、旁边写着答案，就不适合作为首次模拟；可以复印合法自用空白页或选择未填写版本。解析页的思路批注有时有帮助，但错误更正应有可靠依据。

还要检查年份是否连续、页码是否齐全、图表和公式是否清晰。扫描模糊到看不清下标，会让理工科题目失去意义；缺少附件数据也可能导致整题无法完成。

## 用题型矩阵指导复习

我会建立“年份—题型—章节—错误原因”简表，观察哪些能力反复出现，再回教材补基础。矩阵服务时间分配，不把从未出现的章节直接删除，因为课程大纲仍是范围依据。

适合我的二手专业课历年题册，应有清楚课程来源、年份与题型，页面完整可读，答案可验证，并能在学完基础后用于模拟。它帮助理解考试，不替代课堂范围。

考试结束后，我不会把当年回忆题直接当作精确真题加入题册。若要记录，只标注来源、回忆时间和不确定项，与正式可核材料分开，避免下一届把模糊记忆误当成原题。', _utf8mb4'["历年题","课程代码","期末复习","购买经验"]', 0, 0, @seed_author_id, DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 404 DAY), DATE_SUB(CURRENT_TIMESTAMP, INTERVAL 404 DAY), 0
