CREATE TEMPORARY TABLE `seed_post_content_guard` (
  `isValid` TINYINT NOT NULL,
  CONSTRAINT `chk_seed_post_content_guard` CHECK (`isValid` = 1)
);
INSERT INTO `seed_post_content_guard` (`isValid`)
SELECT CASE WHEN
  (SELECT COUNT(*) FROM `post` p JOIN `user` u ON u.`id` = p.`userId`
   WHERE p.`isDelete` = 0 AND u.`userAccount` REGEXP _utf8mb4'^seed_post_author_(0[1-9]|1[0-9]|20)$') = 260
  AND (SELECT COUNT(DISTINCT p.`title`) FROM `post` p JOIN `user` u ON u.`id` = p.`userId`
       WHERE p.`isDelete` = 0 AND u.`userAccount` REGEXP _utf8mb4'^seed_post_author_(0[1-9]|1[0-9]|20)$') = 260
  AND (SELECT COALESCE(SUM(CHAR_LENGTH(p.`content`)), 0) FROM `post` p JOIN `user` u ON u.`id` = p.`userId`
       WHERE p.`isDelete` = 0 AND u.`userAccount` REGEXP _utf8mb4'^seed_post_author_(0[1-9]|1[0-9]|20)$') >= 280000
  AND NOT EXISTS (SELECT 1 FROM `post` p JOIN `user` u ON u.`id` = p.`userId`
                  WHERE p.`isDelete` = 0 AND u.`userAccount` REGEXP _utf8mb4'^seed_post_author_(0[1-9]|1[0-9]|20)$'
                    AND (NOT JSON_VALID(p.`tags`) OR JSON_LENGTH(p.`tags`) < 3 OR JSON_LENGTH(p.`tags`) > 6))
THEN 1 ELSE 0 END;
DROP TEMPORARY TABLE `seed_post_content_guard`;

COMMIT;
